window.businessUi = (() => {
  const esc = accountEscape;
  let dashboard = null, timer = null, request = 0, busy = false, upgradeError = '';
  const collectionJobs = new Map(), cashCelebrations = new Set();
  let collectionVersion = 0;
  const collectionRequests = new Map(), cashMessages = new Map();
  function pendingCollection(shopId) {
    if(!account)return null;
    const key=`jg:store-cash:${account.id}:${shopId}`;
    try{return collectionRequests.get(key)||localStorage.getItem(key);}catch{return collectionRequests.get(key)||null;}
  }
  function collectCashMarkup(shop) {
    const collecting=collectionJobs.has(shop.id),amount=shop.cashReady||0,pending=pendingCollection(shop.id);
    const message=cashMessages.get(shop.id);
    return `<div class="business-cash"><button type="button" class="business-cash-button${collecting?' is-collecting':''}" data-business="collect-cash" data-shop="${esc(shop.id)}" ${collecting||(!amount&&!pending)?'disabled':''} aria-label="${esc(t('Collect cash','Kasse einsammeln'))}: ${esc(shop.name||typeName(shop.type))} · ${esc(justizEuro(amount))}"><svg viewBox="0 0 48 48" fill="none" aria-hidden="true"><path d="m18 8 6 3 6-3-4 10c10 5 14 12 13 18-1 6-7 8-15 8S10 42 9 36c-1-6 3-13 13-18L18 8Z" fill="currentColor" opacity=".2"/><path d="m18 8 6 3 6-3-4 10c10 5 14 12 13 18-1 6-7 8-15 8S10 42 9 36c-1-6 3-13 13-18L18 8Zm1 11h10" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><text x="24" y="36" text-anchor="middle" font-size="16" font-weight="700" fill="currentColor">€</text></svg><span class="business-cash-copy"><span>${collecting?t('Collecting…','Wird eingesammelt …'):pending?t('Retry collection','Erneut einsammeln'):amount?t('Collect cash','Kasse einsammeln'):t('Register empty','Kasse leer')}</span><strong>${justizEuro(amount)}</strong></span></button><small class="business-cash-status" role="status" aria-live="polite">${message?t(`Collected ${justizEuro(message)}!`,`${justizEuro(message)} eingesammelt!`):''}</small></div>`;
  }
  async function cashCelebration(button,amount,job) {
    if(!amount||!button?.isConnected||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
    const origin=button.getBoundingClientRect(),coinOrigin=button.querySelector('svg')?.getBoundingClientRect()||origin;
    const layer=document.createElement('div');layer.className='business-cash-celebration';layer.setAttribute('aria-hidden','true');job.layer=layer;
    layer.style.setProperty('--cash-x',`${coinOrigin.left+coinOrigin.width/2}px`);
    layer.style.setProperty('--cash-y',`${coinOrigin.top+coinOrigin.height/2}px`);
    layer.innerHTML=`<span class="business-cash-reward">+${esc(justizEuro(amount))}</span>${Array.from({length:14},()=>'<span class="business-cash-coin">€</span>').join('')}`;
    document.body.append(layer);cashCelebrations.add(job);
    try {
      const reward=layer.querySelector('.business-cash-reward'),width=reward.getBoundingClientRect().width;
      reward.style.left=`${Math.max(12+width/2,Math.min(innerWidth-12-width/2,origin.left+origin.width/2))}px`;
      job.animations=[reward.animate([{opacity:0,transform:'translate(-50%,0) scale(.9)'},{opacity:1,offset:.2,transform:'translate(-50%,-18px) scale(1)'},{opacity:0,transform:'translate(-50%,-48px) scale(.95)'}],{duration:480,easing:'ease-out'})];
      for(const [i,coin] of [...layer.querySelectorAll('.business-cash-coin')].entries()){
        const dx=(i-6.5)*16,height=40+i%5*11,fall=36+i%4*12,spin=(i%2?1:-1)*(180+i*27);
        job.animations.push(coin.animate([{opacity:0,transform:'translate(-50%,-50%) scale(.4)'},{opacity:1,offset:.14,transform:`translate(${dx*.2}px,${-height*.55}px) rotate(${spin*.15}deg) scale(1)`},{opacity:1,offset:.45,transform:`translate(${dx*.6}px,${-height}px) rotate(${spin*.45}deg) scale(1)`},{opacity:0,transform:`translate(${dx}px,${fall}px) rotate(${spin}deg) scale(.7)`}],{duration:380+i%4*35,delay:i%3*8,easing:'linear'}));
      }
      await Promise.all(job.animations.map(animation=>animation.finished.catch(()=>{})));
    } finally { layer.remove();cashCelebrations.delete(job); }
  }
  function paintCashControl(shopId) {
    const shop=ownedShop(shopId);if(!shop)return;
    for(const control of accountContent.querySelectorAll(`[data-business="collect-cash"][data-shop="${CSS.escape(shopId)}"]`)){
      const wrapper=control.closest('.business-cash'),focused=wrapper.contains(document.activeElement);
      const replacement=document.createElement('div');replacement.innerHTML=collectCashMarkup(shop);
      const next=replacement.firstElementChild;wrapper.replaceWith(next);
      if(focused){const status=next.querySelector('.business-cash-status');status.tabIndex=-1;status.focus({preventScroll:true});}
    }
  }
  async function collectCash(button) {
    const shop=ownedShop(button.dataset.shop);if(!account||!shop||collectionJobs.has(shop.id)||(!shop.cashReady&&!pendingCollection(shop.id)))return;
    const job={shopId:shop.id,owner:account.id,visit:accountVisit,animations:[]};collectionJobs.set(shop.id,job);request++;
    const key=`jg:store-cash:${job.owner}:${shop.id}`;let requestId=collectionRequests.get(key);
    try{requestId=requestId||localStorage.getItem(key);}catch{}
    requestId=requestId||crypto.randomUUID();collectionRequests.set(key,requestId);try{localStorage.setItem(key,requestId);}catch{}
    paintCashControl(shop.id);
    const current=()=>collectionJobs.get(shop.id)===job&&job.owner===account?.id&&job.visit===accountVisit;
    try{
      const result=await accountApi('businesses/collect',{shopId:shop.id,requestId});
      collectionRequests.delete(key);try{localStorage.removeItem(key);}catch{}
      if(!current())return;
      request++;
      // Concurrent replies may arrive out of order; keep the newest server balance.
      if((result.collectionVersion||0)>=collectionVersion){collectionVersion=result.collectionVersion||0;updateAccount(result.user);}
      cashMessages.set(shop.id,result.collection.amount);
      const localShop=ownedShop(shop.id);if(localShop)localShop.cashReady=result.cashReady;
      const control=accountContent.querySelector(`[data-business="collect-cash"][data-shop="${CSS.escape(shop.id)}"]`);
      // The spill never gates the next collection, including another store.
      void cashCelebration(control,result.collection.amount,job).catch(()=>{});
    }catch(error){
      if(error.code){collectionRequests.delete(key);try{localStorage.removeItem(key);}catch{}}
      if(current())showToast(error.message);
    }finally{
      if(current()){
        collectionJobs.delete(shop.id);request++;paintCashControl(shop.id);
        // Refresh statistics independently of the payment and visual feedback.
        if(!collectionJobs.size)void refresh(job.visit,false).catch(()=>{});
      }
    }
  }

  const ui=window.shopUi,typeName=ui.typeName,sizeName=ui.sizeName;
  const ownedShop=id=>dashboard?.shops.find(shop=>shop.id===id);
  const drafts=new Map(),quickJobs=new Map();
  let task=null,returnFocus=null;
  const dialog=document.createElement('dialog');dialog.className='shop-task';dialog.setAttribute('aria-labelledby','shop-task-title');document.body.append(dialog);
  const businessSurface=()=>['/businesses','/stores'].includes(currentAccountPage);
  function draftFor(shop){const key=`${account.id}:${shop.id}`;if(!drafts.has(key))drafts.set(key,{settings:{name:shop.name||'',motto:shop.motto||'',color:shop.color,bannerUrl:shop.bannerUrl||'',iconUrl:shop.iconUrl||'',securityGuard:shop.securityGuard,profitMargin:shop.profitMargin},expected:{name:shop.name||'',motto:shop.motto||'',color:shop.color,bannerUrl:shop.bannerUrl||'',iconUrl:shop.iconUrl||'',securityGuard:shop.securityGuard,profitMargin:shop.profitMargin},add:[],remove:[],dirty:false,error:'',saved:false});return drafts.get(key);}
  function groupedRestockItems(items) {
    const groups=new Map();
    for(const item of items){const key=JSON.stringify([item.title,item.price,item.image,item.rarity,item.estimatedValueTokens,item.acquisitionCost]);if(!groups.has(key))groups.set(key,{...item,items:[]});groups.get(key).items.push(item);}
    return [...groups.values()].sort((a,b)=>a.title.localeCompare(b.title)||a.price-b.price);
  }
  function autoRestockCounts(groups,shelfTitles,space){
    const counts=groups.map(()=>0),seen=new Set(shelfTitles);let left=Math.max(0,space);
    groups.forEach((g,i)=>{if(left&&!seen.has(g.title)){counts[i]++;seen.add(g.title);left--;}});
    while(left){let added=false;groups.forEach((g,i)=>{if(left&&counts[i]<g.items.length){counts[i]++;left--;added=true;}});if(!added)break;}return counts;
  }
  function quickRestockMarkup(id){const shop=ownedShop(id);if(!shop)return '';const available=dashboard.inventory.some(i=>i.type===shop.type),pending=quickJobs.has(id);return `<button class="secondary-button business-quick-button" data-business="quick-restock" data-shop="${esc(id)}" ${pending||!available||shop.stock.length>=shop.capacity?'disabled':''}>${pending?t('Restocking…','Wird aufgefüllt …'):t('Quick restock','Schnell auffüllen')} <span aria-hidden="true">↯</span></button>`;}
  function metrics(entries){return `<dl class="shop-metrics">${entries.map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl>`;}
  function shopCard(shop){return `<article class="shop-card business-shop shop-color-${esc(shop.type)}"><div class="shop-card-picture">${ui.banner(shop)}${ui.icon(shop)}<span class="shop-badge">${esc(sizeName(shop.size))}</span><span class="shop-state">${shop.abandoned?t('Abandoned','Verlassen'):shop.stock.length?t('Open','Geöffnet'):t('Needs stock','Waren fehlen')}</span></div><div class="shop-card-content"><small>${esc(typeName(shop.type))}</small><h2>${esc(shop.name||typeName(shop.type))}</h2><a class="shop-review-rating" href="${esc(ui.href(shop,'reviews'))}" data-page>${shop.rating == null ? t('No reviews yet','Noch keine Bewertungen') : `<span aria-hidden="true">★</span><span>${number(shop.rating,1)} / 5</span><span>· ${number(shop.reviewCount)} ${t(shop.reviewCount===1?'review':'reviews',shop.reviewCount===1?'Bewertung':'Bewertungen')}</span>`}</a>${window.storeReputationUi?.meter(shop)||''}${window.storeReputationUi?.breakdown(shop)||''}${metrics([[t('Revenue today','Umsatz heute'),justizEuro(shop.revenueToday)],[t('Sales today','Verkäufe heute'),number(shop.salesToday)]])}<div class="shop-capacity"><span>${t('Shelves','Regale')}</span><strong>${shop.stock.length} / ${shop.capacity}</strong><progress value="${shop.stock.length}" max="${shop.capacity}" aria-label="${t('Shelf capacity used','Belegte Regalplätze')}"></progress></div>${shop.abandoned?`<p role="status">${t('Add new stock to recover this store before another player buys it.','Füge neue Waren hinzu, bevor ein anderer Spieler deinen Laden kauft.')}</p>`:''}${collectCashMarkup(shop)}<a class="primary-button" href="${esc(ui.href(shop))}" data-page>${t('Manage store','Laden verwalten')} →</a><div class="shop-shortcuts"><button class="secondary-button" data-business="open-restock" data-shop="${esc(shop.id)}">${t('Stock','Waren')}</button><button class="secondary-button" data-business="open-edit" data-shop="${esc(shop.id)}">${t('Settings','Einstellungen')}</button>${quickRestockMarkup(shop.id)}</div>${shop.upgrade?upgradeMarkup(shop):shop.nextUpgrade?`<a class="shop-upgrade-link" href="${esc(ui.href(shop))}" data-page>${t('Upgrade store','Laden ausbauen')} →</a>`:''}</div></article>`;}
  function shopsView(){if(!account)return pageHeading(t('Your stores','Deine Läden'))+`<a href="/login" data-page class="primary-button">${t('Sign in','Anmelden')}</a>`;const shops=dashboard?.shops||[],total=key=>shops.reduce((sum,s)=>sum+(s[key]||0),0);return `<div class="stores-workspace"><header class="shop-page-heading"><h1 tabindex="-1">${t('Your stores','Deine Läden')}</h1><a class="secondary-button" href="/stores" data-page>${t('Stores','Läden')} ↗</a></header>${metrics([[t('Ready to collect','Zum Einsammeln bereit'),justizEuro(total('cashReady'))],[t('Revenue today','Umsatz heute'),justizEuro(total('revenueToday'))],[t('Sales today','Verkäufe heute'),number(total('salesToday'))],[t('Locations','Standorte'),`${shops.length} / ${dashboard?.maxStores||3}`]])}<div class="shop-card-grid">${shops.map(shopCard).join('')}${shops.length<(dashboard?.maxStores||3)?`<a class="shop-open-card" href="/town?view=open" data-page><span aria-hidden="true">＋</span><strong>${t('Open a store','Laden eröffnen')}</strong><small>${t('Choose a location in town','Wähle einen Standort in der Stadt')} →</small></a>`:''}</div><div data-shop-activity></div></div>`;}
  function upgradeMarkup(shop,confirm=false){
    const work=shop.upgrade,offer=shop.nextUpgrade;
    if(work){
      const remaining=Math.max(0,Math.ceil((work.completesAt-Date.now())/60000)),hours=Math.floor(remaining/60),minutes=remaining%60;
      const ready=new Date(work.completesAt).toLocaleString(uiLocale(),{dateStyle:'medium',timeStyle:'short'});
      return `<section class="shop-upgrade is-building" aria-label="${t('Store upgrade','Ladenausbau')}"><header><span aria-hidden="true">🏗</span><h3>${t('Upgrading to','Ausbau zu')} ${esc(sizeName(work.toSize))}</h3></header><progress value="${Math.max(0,Math.min(work.completesAt-work.startedAt,Date.now()-work.startedAt))}" max="${work.completesAt-work.startedAt}" aria-label="${t('Upgrade progress','Ausbaufortschritt')}"></progress><p role="status">${remaining?`${hours}h ${minutes}m`:t('Finishing…','Wird fertiggestellt …')} · <time datetime="${new Date(work.completesAt).toISOString()}">${esc(ready)}</time></p><small>${t('Your store keeps trading at its current size until completion.','Dein Laden handelt bis zur Fertigstellung in seiner bisherigen Größe weiter.')}</small></section>`;
    }
    if(!offer)return confirm?`<p>${t('Your store is already the largest size.','Dein Laden hat bereits die größte Größe.')}</p>`:'';
    const disabled=busy||!offer.unlocked||shop.abandoned||account.tokens<offer.cost;
    return `<section class="shop-upgrade" aria-label="${t('Store upgrade','Ladenausbau')}"><header><span aria-hidden="true">🏗</span><h3>${t('Upgrade to','Ausbauen zu')} ${esc(sizeName(offer.targetSize))}</h3></header><dl><div><dt>${t('Upgrade price','Ausbaupreis')}</dt><dd>${justizEuro(offer.cost)}</dd></div><div><dt>${t('New purchase','Neukauf')}</dt><dd><s>${justizEuro(offer.purchaseCost)}</s> · −${offer.discountPercent}%</dd></div><div><dt>${t('Build time','Bauzeit')}</dt><dd>${offer.durationHours} ${t('hours','Stunden')}</dd></div><div><dt>${t('Shelf capacity','Regalplätze')}</dt><dd>${shop.capacity} → ${offer.capacity}</dd></div><div><dt>${t('Required level','Benötigtes Level')}</dt><dd>${offer.requiredLevel}</dd></div></dl>${confirm?`<p>${t('Pay now. Your store keeps trading at its current size until completion. The upgrade stays at this location and cannot be cancelled.','Jetzt bezahlen. Dein Laden handelt bis zur Fertigstellung in seiner bisherigen Größe weiter. Der Ausbau bleibt an diesem Standort und kann nicht abgebrochen werden.')}</p>`:''}${!offer.unlocked?`<p role="status">${t('Reach level','Erreiche Level')} ${offer.requiredLevel}.</p>`:shop.abandoned?`<p role="status">${t('Add new stock before upgrading an abandoned store.','Fülle einen verlassenen Laden vor dem Ausbau mit neuen Waren.')}</p>`:account.tokens<offer.cost?`<p role="status">${t('Not enough available cash.','Nicht genug verfügbares Guthaben.')}</p>`:''}<button type="button" class="${confirm?'primary':'secondary'}-button" data-business="${confirm?'start-upgrade':'open-upgrade'}" data-shop="${esc(shop.id)}" ${disabled?'disabled':''}>${confirm?t('Pay & start upgrade','Bezahlen & Ausbau starten'):t('Review upgrade','Ausbau prüfen')}</button>${upgradeError&&confirm?`<p class="account-error" role="alert">${esc(upgradeError)}</p>`:''}</section>`;
  }
  async function startUpgrade(shop){
    if(!account||!shop?.nextUpgrade||busy)return;
    const offer=shop.nextUpgrade,visit=accountVisit,owner=account.id;
    busy=true;upgradeError='';paintTask();
    try{
      await save('businesses/upgrade',{shopId:shop.id,targetSize:offer.targetSize,expectedPrice:offer.cost});
      if(visit===accountVisit&&owner===account?.id)showToast(t('Store upgrade started.','Ladenausbau gestartet.'));
    }catch(error){if(visit===accountVisit&&owner===account?.id)upgradeError=error.message;}
    finally{
      if(visit===accountVisit&&owner===account?.id){
        try{await refresh(visit,false);}catch{}
        busy=false;if(dialog.open){paintTask();dialog.querySelector('h2')?.focus();}else render();
      }
    }
  }
  function settingsMarkup(shop){const d=draftFor(shop),s=d.settings;return `<form class="shop-settings" data-shop-settings="${esc(shop.id)}"><div class="shop-settings-fields"><label>${t('Store name','Ladenname')}<input name="storeName" maxlength="60" value="${esc(s.name)}" placeholder="${esc(typeName(shop.type))}"></label><fieldset class="store-color-picker"><legend>${t('Store color','Ladenfarbe')}</legend>${Object.entries(ui.colors).map(([id,label])=>`<label class="brand-${id}" title="${esc(t(...label))}"><input type="radio" name="color" value="${id}" ${s.color===id?'checked':''}><span class="store-color-swatch" aria-hidden="true"></span><span class="sr-only">${esc(t(...label))}</span></label>`).join('')}</fieldset><label>${t('Banner image','Bannerbild')}<input name="bannerUrl" type="url" maxlength="300" value="${esc(s.bannerUrl)}" placeholder="https://i.imgur.com/abc1234.jpg"><small>${t('Imgur image URL only. Leave blank for the default banner.','Nur Imgur-Bild-URL. Leer lassen für das Standardbanner.')}</small></label><label>${t('Store icon (optional)','Ladenicon (optional)')}<input name="iconUrl" type="url" maxlength="300" value="${esc(s.iconUrl)}" placeholder="https://i.imgur.com/abc1234.png"><small>${t('Imgur image URL only.','Nur Imgur-Bild-URL.')}</small></label><label>${t('Tagline','Ladenspruch')}<input name="motto" maxlength="140" value="${esc(s.motto)}"></label><label>${t('Markup over market estimate','Aufschlag auf Marktschätzung')}<span class="shop-input-unit"><input name="profitMargin" type="number" min="0" max="100" step="1" required value="${s.profitMargin}"> %</span></label><p class="shop-price-example" data-price-example>${t('Market','Markt')} ${justizEuro(100)} → ${t('Shelf','Regal')} ${justizEuro(Math.round(100*(1+s.profitMargin/100)))}</p><label class="shop-check"><input name="securityGuard" type="checkbox" role="switch" ${s.securityGuard?'checked':''}><span>${t('Security guard','Sicherheitsdienst')}<small>${t('5% of profits while active. Reduces NPC theft by 60%. Catch chance after failed player theft: 50% (normally 30%).','5% des Gewinns während des Einsatzes. 60% weniger NPC-Diebstahl. Fangchance nach gescheitertem Spieler-Diebstahl: 50% (sonst 30%).')}</small></span></label></div><aside class="shop-settings-preview" data-brand-preview>${ui.banner({...shop,...s})}${ui.icon({...shop,...s})}<strong data-preview-name>${esc(s.name||typeName(shop.type))}</strong><p data-preview-motto>${esc(s.motto)}</p></aside><footer class="shop-form-footer"><span role="status" data-draft-status>${d.dirty?t('Unsaved changes','Ungespeicherte Änderungen'):d.saved?t('Settings saved','Einstellungen gespeichert'):''}</span><button type="submit" class="primary-button" ${busy?'disabled':''}>${t('Save settings','Einstellungen speichern')}</button><p class="account-error" role="alert">${esc(d.error)}</p>${d.error?`<button type="button" class="secondary-button" data-business="reload-draft" data-shop="${esc(shop.id)}">${t('Reload saved state','Gespeicherten Stand laden')}</button>`:''}</footer></form>${upgradeMarkup(shop)}`;}
  function stockGroups(shop,side){const d=draftFor(shop);d.stockSnapshot=d.stockSnapshot||{inventory:dashboard.inventory.filter(i=>i.type===shop.type),stock:shop.stock};return groupedRestockItems(side==='add'?d.stockSnapshot.inventory:d.stockSnapshot.stock.map(entry=>({...entry.item,id:entry.id,estimatedValueTokens:entry.referencePrice,askingPrice:entry.askingPrice,acquisitionCost:entry.acquisitionCost})));}
  function stockQuantityMinimum(shop,d,side,selected){return side==='remove'?Math.max(0,d.stockSnapshot.stock.length+d.add.length-shop.capacity-d.remove.length+selected):0;}
  const stockCapacityHint=()=>t('Reduce additions first to return fewer items.','Verringere zuerst die Einräummenge, um weniger Artikel zurückzulegen.');
  function stockQuantityLimit(shop,d,side,group,selected){return side==='remove'?group.items.length:Math.max(selected,Math.min(group.items.length,shop.capacity-d.stockSnapshot.stock.length+d.remove.length-d.add.length+selected));}
  function syncStockControls(form,shop,d){for(const input of form.querySelectorAll('[data-side]')){const group=stockGroups(shop,input.dataset.side)[Number(input.dataset.index)],selected=d[input.dataset.side].filter(id=>group.items.some(item=>item.id===id)).length;input.max=stockQuantityLimit(shop,d,input.dataset.side,group,selected);input.min=stockQuantityMinimum(shop,d,input.dataset.side,selected);input.title=Number(input.min)?stockCapacityHint():'';const stepper=input.closest('.shop-stepper');stepper.querySelector('[data-step="-1"]').disabled=busy||selected<=Number(input.min);stepper.querySelector('[data-step="1"]').disabled=busy||selected>=Number(input.max);}}
  function stockMarkup(original,inTask=false){const d=draftFor(original);stockGroups(original,'add');const shop={...original,stock:d.stockSnapshot.stock},before=shop.stock.length,after=shop.stock.length+d.add.length-d.remove.length;return `<form data-shop-stock="${esc(shop.id)}" class="shop-stock-form"><div class="shop-stock-heading"><h3>${t('Inventory → Shelves','Inventar → Regale')}</h3><button class="secondary-button" type="button" data-business="auto-restock" data-shop="${esc(shop.id)}">${t('Auto fill','Automatisch füllen')}</button></div><div class="shop-stock-columns">${['add','remove'].map(side=>{const groups=stockGroups(shop,side);return `<section><h3>${side==='add'?t('Inventory','Inventar'):t('On shelves','Im Regal')}</h3><div class="shop-stock-list">${groups.map((g,index)=>{const selected=d[side].filter(id=>g.items.some(i=>i.id===id)).length,market=g.estimatedValueTokens||g.price,limit=stockQuantityLimit(shop,d,side,g,selected),minimum=stockQuantityMinimum(shop,d,side,selected),shelf=g.askingPrice||(shop.profitMargin?Math.max(market+1,Math.round(market*(1+shop.profitMargin/100))):market);return `<div class="shop-stock-row">${g.image?`<img src="${esc(g.image)}" alt="" loading="lazy">`:ui.art(shop.type)}<div class="shop-stock-copy"><strong>${esc(g.title)}</strong><small>${g.items.length}× · ${esc(g.rarity?rarityLabel(g.rarity):'')} · ${t('Market','Markt')} ${justizEuro(market)} · ${t('Shelf','Regal')} ${justizEuro(shelf)}</small></div><label class="shop-stepper"><span class="shop-transfer-label">${side==='add'?t('Add','Einräumen'):t('Return','Zurücklegen')}</span><span class="sr-only">${esc(g.title)} · ${side==='add'?t('Add','Einräumen'):t('Return','Zurücklegen')}</span><button type="button" data-step="-1" ${busy||selected<=minimum?'disabled':''} aria-label="${t('Decrease quantity','Anzahl verringern')}">−</button><input type="number" name="quantity" data-side="${side}" data-index="${index}" min="${minimum}" title="${minimum?esc(stockCapacityHint()):''}" max="${limit}" value="${selected}" inputmode="numeric"><button type="button" data-step="1" ${busy||selected>=limit?'disabled':''} aria-label="${t('Increase quantity','Anzahl erhöhen')}">+</button></label></div>`;}).join('')||`<p class="shop-empty">${t('No matching items.','Keine passenden Artikel.')}</p>`}</div></section>`;}).join('')}</div><footer class="shop-form-footer"><div role="status"><strong data-stock-summary>${before} → ${after} / ${shop.capacity}</strong><small> · +${d.add.length} / −${d.remove.length} ${t('pending','vorgemerkt')}</small></div><button class="primary-button" type="submit" ${busy||(!d.add.length&&!d.remove.length)||after>shop.capacity?'disabled':''}>${t('Apply stock changes','Warenänderungen anwenden')}</button><p class="account-error" role="alert">${esc(d.error)}</p>${d.error?`<button type="button" class="secondary-button" data-business="reload-draft" data-shop="${esc(shop.id)}">${t('Reload saved state','Gespeicherten Stand laden')}</button>`:''}</footer>${!inTask?`<a class="shop-supply-link" href="/auction-house?stock=${encodeURIComponent(shop.type)}&returnShop=${encodeURIComponent(shop.id)}&returnTo=${encodeURIComponent(ui.returnTo())}" data-page>${t('Find compatible stock','Passende Waren finden')} ↗</a>`:''}</form>`;}
  function ownerView(store){const shop=ownedShop(store.id);if(!shop)return pageHeading(t('Loading your store…','Dein Laden wird geladen …'));let tab=new URLSearchParams(location.search).get('tab')||'overview';if(!['overview','stock','reviews','settings'].includes(tab))tab='overview';return `<div class="stores-workspace"><a class="shop-back" href="${esc(ui.returnTo())}" data-page>← ${ui.returnTo().startsWith('/businesses')?t('Your stores','Deine Läden'):ui.returnTo().startsWith('/town')?t('Store locations','Ladenstandorte'):t('Stores','Läden')}</a>${ui.header({...store,...shop})}<nav class="shop-tabs" aria-label="${t('Store management','Ladenverwaltung')}">${[['overview',t('Overview','Übersicht')],['stock',t('Stock','Waren')],['reviews',t('Reviews','Bewertungen')],['settings',t('Settings','Einstellungen')]].map(([id,label])=>`<a href="${esc(ui.href(shop,id))}" data-page ${tab===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav><section class="shop-surface">${tab==='settings'?settingsMarkup(shop):tab==='stock'?stockMarkup(shop):tab==='reviews'?window.storeUi.reviews(store):`${metrics([[t('Revenue today','Umsatz heute'),justizEuro(shop.revenueToday)],[t('Sales today','Verkäufe heute'),number(shop.salesToday)],[t('Popularity','Beliebtheit'),`${number(shop.popularityPercent)}%`],[t('Visitors','Besucher'),number(shop.visitors)]])}${window.storeReputationUi?.breakdown(shop,true)||''}${upgradeMarkup(shop)}<div class="shop-overview-actions">${collectCashMarkup(shop)}${quickRestockMarkup(shop.id)}<a class="secondary-button" href="${esc(ui.href(shop,'stock'))}" data-page>${t('Manage stock','Warenbestand verwalten')} →</a></div>${metrics([[t('Total revenue','Umsatz gesamt'),justizEuro(shop.revenue)],[t('Realized trading profit','Realisierter Handelsgewinn'),justizEuro(shop.realizedTradingProfit)],[t('Guard costs paid','Gezahlte Sicherheitskosten'),justizEuro(shop.securityGuardFees||0)],[t('NPC theft risk / day','NPC-Diebstahlrisiko / Tag'),`${number(shop.npcTheftChancePercent,2)}%`],[t('Total sales','Verkäufe gesamt'),number(shop.sales)],[t('Reward proceeds','Belohnungserlöse'),justizEuro(shop.rewardProceeds)],[t('Sales with unknown cost','Verkäufe mit unbekannten Kosten'),number(shop.unknownCostSales)],[t('Buying rate','Kaufrate'),`${number(shop.buyChancePercent,1)}%`],[t('Markup over estimate','Aufschlag auf Schätzung'),`${shop.profitMargin}%`]])}<p>${shop.stock.length} / ${shop.capacity} ${t('on shelves','im Regal')}</p><div data-shop-activity></div>`}</section></div>`;}
  function paintTask(){if(!task)return;const shop=ownedShop(task.id);if(!shop){dialog.close();return;}dialog.innerHTML=`<header class="shop-task-header"><div><small>${esc(shop.name||typeName(shop.type))}</small><h2 id="shop-task-title" tabindex="-1">${task.view==='upgrade'?t('Store upgrade','Ladenausbau'):task.view==='stock'?t('Manage stock','Warenbestand verwalten'):t('Store settings','Ladeneinstellungen')}</h2></div><button class="dialog-close" data-business="close-task" aria-label="${t('Close','Schließen')}">×</button></header><div class="shop-task-body">${task.view==='upgrade'?upgradeMarkup(shop,true):task.view==='stock'?stockMarkup(shop,true):settingsMarkup(shop)}</div>`;}
  function render(){if(currentAccountPage==='/stores'){window.storeUi.render();return;}if(currentAccountPage!=='/businesses')return;accountContent.innerHTML=shopsView();window.storeUi.showEvents();}
  async function refresh(visit,repaint=true){const current=++request,owner=account?.id,shops=owner?await accountApi('businesses'):null;if(current!==request||visit!==accountVisit||owner!==account?.id)return;dashboard=shops;for(const shop of shops?.shops||[]){const d=drafts.get(`${owner}:${shop.id}`);if(d&&!isInteracting()){if(!d.add.length&&!d.remove.length)d.stockSnapshot=null;if(!d.dirty){d.settings={name:shop.name||'',motto:shop.motto||'',color:shop.color,bannerUrl:shop.bannerUrl||'',iconUrl:shop.iconUrl||'',securityGuard:shop.securityGuard,profitMargin:shop.profitMargin};d.expected={...d.settings};}}}if(owner){const session=await accountApi('me');if(current!==request||visit!==accountVisit||owner!==account?.id)return;updateAccount(session.user);}if(repaint&&!isInteracting())render();}
  async function load(visit){if(account)await window.storeUi.loadEvents(visit);if(visit!==accountVisit)return;await refresh(visit,false);if(visit!==accountVisit)return;timer=setInterval(()=>{if(!document.hidden&&!busy)refresh(visit).then(()=>{if(task?.view==='upgrade'&&dialog.open&&!busy&&dialog.querySelector('.shop-upgrade.is-building')){const shop=ownedShop(task.id);if(shop)dialog.querySelector('.shop-task-body').innerHTML=upgradeMarkup(shop,true);}}).catch(()=>{});},30000);}
  function stop(){clearInterval(timer);request++;dashboard=null;busy=false;upgradeError='';task=null;dialog.close();collectionJobs.clear();collectionVersion=0;cashMessages.clear();for(const job of cashCelebrations){job.animations.forEach(a=>a.cancel());job.layer?.remove();}cashCelebrations.clear();}
  function isInteracting(){return dialog.open||busy||Boolean(document.activeElement?.closest('[data-shop-settings],[data-shop-stock]'));}
  async function save(route,payload){const key=`jg:shop-draft:${account.id}:${route}:${JSON.stringify(payload)}`;let id;try{id=localStorage.getItem(key);}catch{}id=id||crypto.randomUUID();try{localStorage.setItem(key,id);}catch{}try{const result=await accountApi(route,{...payload,requestId:id});try{localStorage.removeItem(key);}catch{}return result;}catch(error){if(error.code)try{localStorage.removeItem(key);}catch{}throw error;}}
  async function quickRestock(button){const shop=ownedShop(button.dataset.shop);if(!shop||quickJobs.has(shop.id))return;const groups=groupedRestockItems(dashboard.inventory.filter(i=>i.type===shop.type)),counts=autoRestockCounts(groups,shop.stock.map(e=>e.item.title),shop.capacity-shop.stock.length),addIds=groups.flatMap((g,i)=>g.items.slice(0,counts[i]).map(e=>e.id));if(!addIds.length)return;const visit=accountVisit,owner=account.id;quickJobs.set(shop.id,true);button.disabled=true;button.classList.add('is-packing');try{await save('businesses/stock/transfer',{shopId:shop.id,addIds,removeIds:[]});if(visit===accountVisit&&owner===account?.id){await refresh(visit,false);const d=drafts.get(`${owner}:${shop.id}`);if(d&&!d.add.length&&!d.remove.length)d.stockSnapshot=null;showToast(t('Shelves restocked.','Regale aufgefüllt.'));}}catch(error){if(visit===accountVisit)showToast(error.message);}finally{quickJobs.delete(shop.id);if(visit===accountVisit){if(dialog.open)paintTask();else render();}}}
  document.addEventListener('click',event=>{const b=event.target.closest('[data-business]');if(!b||!businessSurface())return;const action=b.dataset.business;if(action==='start-upgrade'){void startUpgrade(ownedShop(b.dataset.shop));return;}if(action==='open-upgrade'){upgradeError='';const wasOpen=dialog.open;task={id:b.dataset.shop,view:'upgrade'};if(!wasOpen)returnFocus=b;paintTask();if(!wasOpen)dialog.showModal();dialog.querySelector('h2').focus();return;}if(action==='collect-cash'){void collectCash(b);return;}if(action==='quick-restock'){void quickRestock(b);return;}if(action==='open-edit'||action==='open-restock'){task={id:b.dataset.shop,view:action==='open-edit'?'settings':'stock'};returnFocus=b;paintTask();dialog.showModal();dialog.querySelector('h2').focus();}if(action==='close-task')dialog.close();if(action==='reload-draft'){drafts.delete(`${account.id}:${b.dataset.shop}`);void refresh(accountVisit,false).then(()=>dialog.open?paintTask():render());}if(action==='auto-restock'){const shop=ownedShop(b.dataset.shop),d=draftFor(shop),groups=stockGroups(shop,'add'),counts=autoRestockCounts(groups,shop.stock.filter(e=>!d.remove.includes(e.id)).map(e=>e.item.title),shop.capacity-shop.stock.length+d.remove.length);d.add=groups.flatMap((g,i)=>g.items.slice(0,counts[i]).map(e=>e.id));d.saved=false;if(dialog.open)paintTask();else render();const host=dialog.open?dialog:accountContent;host.querySelector(`[data-business="auto-restock"][data-shop="${CSS.escape(shop.id)}"]`)?.focus({preventScroll:true});}});
  document.addEventListener('click',event=>{const b=event.target.closest('.shop-stepper [data-step]');if(!b)return;const input=b.parentElement.querySelector('input');input.value=Math.max(Number(input.min),Math.min(Number(input.max),Number(input.value)+Number(b.dataset.step)));input.dispatchEvent(new Event('change',{bubbles:true}));});
  document.addEventListener('input',event=>{const form=event.target.closest('[data-shop-settings]');if(!form)return;const shop=ownedShop(form.dataset.shopSettings);if(!shop)return;const d=draftFor(shop);d.settings={name:form.elements.storeName.value,motto:form.elements.motto.value,color:form.elements.color.value,bannerUrl:form.elements.bannerUrl.value,iconUrl:form.elements.iconUrl.value,profitMargin:Number(form.elements.profitMargin.value),securityGuard:form.elements.securityGuard.checked};d.dirty=Object.keys(d.settings).some(key=>d.settings[key]!==d.expected[key]);d.saved=false;form.querySelector('[data-draft-status]').textContent=d.dirty?t('Unsaved changes','Ungespeicherte Änderungen'):'';const preview=form.querySelector('[data-brand-preview]');preview.innerHTML=ui.banner({...shop,...d.settings})+ui.icon({...shop,...d.settings})+'<strong data-preview-name></strong><p data-preview-motto></p>';form.querySelector('[data-preview-name]').textContent=d.settings.name||typeName(shop.type);form.querySelector('[data-preview-motto]').textContent=d.settings.motto;form.querySelector('[data-price-example]').textContent=`${t('Market','Markt')} ${justizEuro(100)} → ${t('Shelf','Regal')} ${justizEuro(Math.round(100*(1+d.settings.profitMargin/100)))}`;});
  document.addEventListener('change',event=>{const input=event.target,form=input.closest('[data-shop-stock]');if(!form||!input.matches('[data-side]'))return;const shop=ownedShop(form.dataset.shopStock),d=draftFor(shop),side=input.dataset.side,g=stockGroups(shop,side)[Number(input.dataset.index)],ids=new Set(g.items.map(i=>i.id));const selected=d[side].filter(id=>ids.has(id)).length,limit=stockQuantityLimit(shop,d,side,g,selected);const minimum=stockQuantityMinimum(shop,d,side,selected),value=Math.max(minimum,Math.min(limit,Math.floor(Number(input.value)||0)));d[side]=[...d[side].filter(id=>!ids.has(id)),...g.items.slice(0,value).map(i=>i.id)];d.saved=false;const before=d.stockSnapshot.stock.length,after=before+d.add.length-d.remove.length;form.querySelector('[data-stock-summary]').parentElement.innerHTML=`<strong data-stock-summary>${before} → ${after} / ${shop.capacity}</strong><small> · +${d.add.length} / −${d.remove.length} ${t('pending','vorgemerkt')}</small>`;form.querySelector('[type="submit"]').disabled=busy||(!d.add.length&&!d.remove.length)||after>shop.capacity;input.value=value;syncStockControls(form,shop,d);});
  document.addEventListener('submit',async event=>{const form=event.target;if(!businessSurface()||!form.matches('[data-shop-settings],[data-shop-stock]'))return;event.preventDefault();if(busy||!account)return;const id=form.dataset.shopSettings||form.dataset.shopStock,shop=ownedShop(id),d=draftFor(shop),settings=Boolean(form.dataset.shopSettings),visit=accountVisit,owner=account.id;busy=true;d.error='';form.querySelector('[type="submit"]').disabled=true;try{await save(settings?'businesses/settings':'businesses/stock/transfer',settings?{shopId:id,...d.settings,expected:d.expected}:{shopId:id,addIds:d.add,removeIds:d.remove});if(visit!==accountVisit||owner!==account?.id)return;await refresh(visit,false);if(settings){const saved=ownedShop(id);d.settings={name:saved.name||'',motto:saved.motto||'',color:saved.color,bannerUrl:saved.bannerUrl||'',iconUrl:saved.iconUrl||'',securityGuard:saved.securityGuard,profitMargin:saved.profitMargin};d.expected={...d.settings};d.dirty=false;}else{d.add=[];d.remove=[];d.stockSnapshot=null;}d.saved=true;showToast(settings?t('Settings saved.','Einstellungen gespeichert.'):t('Stock changes applied.','Warenänderungen angewendet.'));}catch(error){if(visit===accountVisit)d.error=error.message;}finally{busy=false;if(visit===accountVisit){if(dialog.open)paintTask();else render();}}});
  dialog.addEventListener('close',()=>{const id=task?.id,view=task?.view;task=null;const replacement=id?accountContent.querySelector(`[data-business="${view==='upgrade'?'open-upgrade':view==='stock'?'open-restock':'open-edit'}"][data-shop="${CSS.escape(id)}"]`):null;(returnFocus?.isConnected?returnFocus:replacement)?.focus({preventScroll:true});returnFocus=null;});
  document.addEventListener('jg:language',()=>{if(businessSurface()){render();if(dialog.open)paintTask();}});
  return {load,stop,render,refresh,ownerView,ownedShop,quickRestockMarkup,isInteracting};
})();
